function exportPNG(){const message=$('#export-message'),btn=$('#export'),suffix=outputView==='share'?`-${state.shareSize}`:outputView==='vinyl'?'-vinyl':'-cover';message.textContent=`Preparing your ${canvas.width} × ${canvas.height} PNG…`;btn.disabled=true;requestAnimationFrame(()=>{try{const link=document.createElement('a');link.download=`re-album${suffix}.png`;link.href=canvas.toDataURL('image/png');link.click();message.textContent=`Your ${canvas.width} × ${canvas.height} PNG is ready. Keep making things that feel like you.`;notify('PNG downloaded — made by you, for you.')}catch{message.textContent='Export didn’t work. Your edits are still here; try again.'}finally{btn.disabled=false}})}
function resetEditor(){if(outputView==='cover'){if(!window.confirm('Reset this creation to the original template? Your current edits will be cleared.'))return;resetState(activeTemplate);syncSwatches();setMode('quick');notify('Back to the starting point.');return}if(!window.confirm(`Reset only this ${outputView==='vinyl'?'vinyl visual':'share image'} layout? Your cover and other edits will stay as they are.`))return;if(outputView==='vinyl')change({vinylColor:'black',vinylLayout:'sleeve-front',vinylShowTracks:activeTemplate.id==='midnights'});else change({shareSize:'square',shareLayout:'cover-first',shareArtist:activeTemplate.artist==='Your cover'?'':activeTemplate.artist,shareCaption:'',shareLabel:'ON REPEAT',shareShowLabel:false,shareShowRating:false,shareRating:'5/5'});notify('This layout is back to its starting point.')}
async function loadFont(file){const error=$('#font-error');error.textContent='';if(!file)return;const ext=file.name.split('.').pop().toLowerCase();if(!['ttf','otf','woff','woff2'].includes(ext)){error.textContent='Choose a TTF, OTF, WOFF or WOFF2 font file.';return}if(file.size>5*1024*1024){error.textContent='Font files must be 5 MB or smaller.';return}const family=`${file.name.replace(/\.[^.]+$/,'').replace(/[^a-zA-Z0-9 _-]/g,'').trim()||'Imported Font'} ${Date.now().toString().slice(-4)}`,url=URL.createObjectURL(file);try{const font=await new FontFace(family,`url(${url})`).load();document.fonts.add(font);fontUrls.push(url);const option=new Option(`${family} · imported`,family);$('#typeface-select').add(option);change({typeface:family});commitHistory();notify('Font imported for this browser session.')}catch{URL.revokeObjectURL(url);error.textContent='This font file could not be loaded.'}finally{$('#font-input').value=''}}

