$('#album-specific-fields').addEventListener('change',e=>{if(e.target.id==='window-mode'){const value=e.target.value;change({windowMode:value});$('#window-text').disabled=value==='image';return}if(e.target.id==='window-text'){commitHistory();return}if(e.target.id==='window-alignment'){change({windowAlignment:e.target.value});return}if(e.target.id==='window-image-input')loadWindowImage(e.target.files[0])});$('#album-specific-fields').addEventListener('input',e=>{if(e.target.id==='window-text'){state.windowText=e.target.value;drawArtwork()}});$('#album-specific-fields').addEventListener('click',e=>{if(e.target.id==='window-remove-image'){if(windowImageUrl){URL.revokeObjectURL(windowImageUrl);windowImageUrls=windowImageUrls.filter(url=>url!==windowImageUrl)}windowImageObject=null;windowImageUrl='';state.windowMode='text';syncControls();$('#window-image-input').value='';$('#window-remove-image').hidden=true;drawArtwork();commitHistory();notify('Window image removed.')}});
