$('#font-size-input').addEventListener('input',e=>{const px=Number(e.target.value);if(Number.isFinite(px)&&px>=12){state.size=Math.min(300,Math.max(1,px/baseFontSize()*100));$('#size-range').value=state.size;$('#size-value').textContent=`${Math.round(baseFontSize()*state.size/100)} px`;drawArtwork()}});$('#font-size-input').addEventListener('change',()=>{syncControls();commitHistory()});$('#font-input').addEventListener('change',e=>loadFont(e.target.files[0]));
