$('#image-input').addEventListener('change',e=>loadImage(e.target.files[0]));$('#remove-image').addEventListener('click',()=>{imageObject=null;imageUrl='';drawArtwork();$('#remove-image').hidden=true;commitHistory();notify('Image removed from your creation.')});$('#undo').addEventListener('click',()=>{if(historyIndex>0)restoreSnapshot(history[--historyIndex])});$('#redo').addEventListener('click',()=>{if(historyIndex<history.length-1)restoreSnapshot(history[++historyIndex])});$('#reset').addEventListener('click',resetEditor);$('#export').addEventListener('click',exportPNG);
$$('.layer-row').forEach(b=>b.addEventListener('click',()=>{$$('.layer-row').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selectedLayer=b.dataset.layer;canvas.focus()}));
let draggedLayerId='';$$('.layer-row').forEach(row=>{row.addEventListener('dragstart',e=>{draggedLayerId=row.dataset.layer;row.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggedLayerId)});row.addEventListener('dragend',()=>row.classList.remove('dragging'));row.addEventListener('dragover',e=>e.preventDefault());row.addEventListener('drop',e=>{e.preventDefault();const target=row.dataset.layer,from=state.layerOrder.indexOf(draggedLayerId),to=state.layerOrder.indexOf(target);if(from<0||to<0||from===to)return;const order=[...state.layerOrder];order.splice(to,0,order.splice(from,1)[0]);state.layerOrder=order;syncLayerRows();change({layerOrder:order});commitHistory()} )});
canvas.addEventListener('pointerdown',e=>{if(mode!=='free'||outputView!=='cover')return;const p=canvasPoint(e),box=layerBounds(selectedLayer);if(!box)return;canvas._drag={start:p,box,id:selectedLayer};canvas.classList.add('is-dragging');canvas.setPointerCapture(e.pointerId);e.preventDefault()});
canvas.addEventListener('pointermove',e=>{if(mode!=='free'||outputView!=='cover'||!canvas._drag)return;const p=canvasPoint(e),d=canvas._drag,current=layerBounds(d.id);moveLayerTo(d.id,d.box.x+p.x-d.start.x-current.x,d.box.y+p.y-d.start.y-current.y);const box=layerBounds(d.id),snap=snapLayer(box,d.id);moveLayerTo(d.id,snap.x,snap.y);showAlignmentGuides(snap.gx,snap.gy,snap.label)});
function finishCanvasDrag(e){if(!canvas._drag)return;canvas._drag=null;canvas.classList.remove('is-dragging');$('#alignment-guides').className='alignment-guides';commitHistory()}
canvas.addEventListener('pointerup',finishCanvasDrag);canvas.addEventListener('pointercancel',finishCanvasDrag);
canvas.addEventListener('keydown',e=>{if(mode!=='free'||outputView!=='cover')return;const step=e.shiftKey?10:2,offset=(negative,positive)=>e.key===negative?-step:e.key===positive?step:0;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();moveLayerTo(selectedLayer,offset('ArrowLeft','ArrowRight'),offset('ArrowUp','ArrowDown'));clearTimeout(canvas._historyTimer);canvas._historyTimer=setTimeout(commitHistory,250)}});
